```ts
import { z as z4 } from 'zod';

export function serveAppetizerV4Workaround<T extends z4.ZodType>(
  payload: unknown,
  snackSchema: T
): z4.infer<T> | undefined {
  // We tell TS we know there is a 'snack' key, but we'll check what it is later.
  const order = z4.object({ snack: z4.unknown() }).parse(payload);

  // Now we apply the actual schema to the extracted snack.
  const snack = snackSchema.parse(order.snack);
  // const snack: z4.core.output<T>
