For now I've added support in my own codebase by proxying the underlying export and handling zod errors explicitly, anyone interested feel free to use this logic!

```
import type { ZodIssue } from "zod";
import { z as originalZ } from "zod";

function enhanceIssuesWithValues(issues: ZodIssue[], data: unknown) {
  for (const issue of issues) {
    // Navigate to the actual value using the path
    let value = data;
    for (const key of issue.path) {
      if (value && typeof value === "object") {
        value = (value as any)[key];
      } else {
        value = undefined;
        break;
      }
    }

    // Add the actual value to the issue
    (issue as any).actualValue = value;
  }
}

function wrapWithErrorEnhancement<T>(obj: T): T {
  //@ts-expect-error forcing to treat as if original type
  return new Proxy(obj, {
    get(target, prop, receiver) {
      const original = Reflect.get(target, prop, receiver);

      // handle read only properties first
      if (prop.toString().startsWith("_")) {
        return original;
      }

      if (typeof original === "function") {
        return function (...args: any[]) {
          try {
            const result = original.apply(target, args);

            // Wrap returned values recursively
            if (result && typeof result === "object") {
              return wrapWithErrorEnhancement(result);
            }

            return result;
          } catch (error) {
            // Only enhance ZodErrors
            if (error instanceof originalZ.ZodError) {
              const data = args[0];
              if (data !== undefined) {
                enhanceIssuesWithValues(error.issues, data);
                // Update error message to include actual values
                error.message = error.issues
                  .map(
                    (issue) =>
                      `Path: ${JSON.stringify(issue.path)} ${issue.message.replace(/received.+/, `received ${JSON.stringify((issue as any).actualValue) ?? ""}`.substring(0, 60))}.`
                  )
                  .join("\n");
              }
            }
            throw error;
          }
        };
      }

      // Wrap non-function objects too
      if (original && typeof original === "object") {
        return wrapWithErrorEnhancement(original);
      }

      return original;
    }
  });
}

export const z = wrapWithErrorEnhancement(originalZ) as typeof originalZ;

// Explicitly re-export the namespace
export namespace z {
  export type infer<T extends originalZ.ZodType<any, any, any>> = originalZ.infer<T>;
  export type input<T extends originalZ.ZodType<any, any, any>> = originalZ.input<T>;
  export type output<T extends originalZ.ZodType<any, any, any>> = originalZ.output<T>;
  export type ZodType<T = unknown, R = unknown> = originalZ.ZodType<T, R>;
  export type ZodTypeAny = originalZ.ZodTypeAny;
  export type ZodSchema = originalZ.ZodSchema;
  export type ZodArray<T extends ZodTypeAny> = originalZ.ZodArray<T>;
}

export * from "zod";
```

