I'm trying to create a reusable helper function that wraps a Zod object schema to preserve the original key order from the input. 

## What I'm trying to achieve

```typescript

const schema = z.object({
  a: z.string(),
  b: z.string(),
});

// Helper function that preserves key order
function withPreservedKeyOrder<TSchema extends z.ZodTypeAny>(schema: TSchema) {
  const keyOrderMap = new Map<string, string[]>();

  return z
    .preprocess((input) => {
      // Capture original key order before z.object() reorders them
      if (input && typeof input === "object" && !Array.isArray(input)) {
        const serializedKey = serializeObject(input);
        const originalKeyOrder = Object.keys(input);
        keyOrderMap.set(serializedKey, originalKeyOrder);
      }
      return input;
    }, schema)
    .transform((validatedInput): z.output<TSchema> => {
      // Reconstruct object with original key order
      const serializedKey = serializeObject(validatedInput);
      const orderedKeys = keyOrderMap.get(serializedKey) || Object.keys(validatedInput);
      keyOrderMap.delete(serializedKey); // Clean up

      const reorderedOutput: Record<string, unknown> = {};
      for (const key of orderedKeys) {
        if (key in validatedInput) {
          reorderedOutput[key] = validatedInput[key];
        }
      }
      return reorderedOutput as z.output<TSchema>;
    });
}
