For now I've put together a helper function to work around the issue.
It's a slightly different signature that just takes in the keys instead of a mask.

```ts
export function schemaPick<T extends z.ZodObject, K extends keyof T['shape']>(
  schema: T,
  keys: K[]
) {
  const mask = Object.fromEntries(keys.map(key => [key, true])) as {
    [P in K]: true;
  };
  return schema.pick(mask) as z.ZodObject<Prettify<Pick<T['shape'], K>>>;
}
```

